import csv, io, json, os, sys, unicodedata


def norm_id(s):
    return s.strip().lower()


def norm_text(s):
    s = s.casefold()
    s = "".join(c if unicodedata.category(c)[0] == "L" or unicodedata.category(c) == "Nd" else " " for c in s)
    return " ".join(s.split())


def parse_csv(text):
    lines = text.split("\n")
    meta = {}
    i = 0
    while i < len(lines) and (lines[i].startswith("#") or not lines[i].strip()):
        l = lines[i]
        if l.startswith("#") and ":" in l:
            k, v = l[1:].split(":", 1)
            meta[k.strip().lower()] = v.strip()
        i += 1
    recs = []
    rows = list(csv.reader(io.StringIO("\n".join(lines[i:]), newline="")))
    rows = [r for r in rows if r and any(c.strip() for c in r)]
    if not rows:
        return meta, recs
    hdr = [h.strip().lower() for h in rows[0]]
    rk = {}
    for j, h in enumerate(hdr):
        if h.startswith("rank") and h[4:].isdigit():
            rk[int(h[4:])] = j
    bi = hdr.index("ballot")
    ci = hdr.index("contest")
    for r in rows[1:]:
        r = r + [""] * (len(hdr) - len(r))
        marks = {}
        for n, j in rk.items():
            cell = r[j]
            ms = [m for m in cell.split("|") if m.strip()] if cell else []
            if ms:
                marks[n] = [("wi", m[3:]) if m.strip()[:3].upper() == "WI:" else ("c", m)
                            for m in ms]
        recs.append((r[bi], r[ci].strip() if False else r[ci], marks))
    return meta, recs


def parse_jsonl(text):
    meta = {}
    recs = []
    first = True
    for l in text.split("\n"):
        if not l.strip():
            continue
        o = json.loads(l)
        if first:
            meta = o
            first = False
            continue
        marks = {}
        for m in o.get("marks", []):
            n = int(m["rank"])
            if "write_in" in m and m["write_in"] is not None:
                marks.setdefault(n, []).append(("wi", m["write_in"]))
            elif m.get("candidate") is not None:
                marks.setdefault(n, []).append(("c", m["candidate"]))
        recs.append((o["ballot"], o["contest"], marks))
    return meta, recs


def load_records(d):
    cvr = os.path.join(d, "cvr")
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p):
            continue
        if name.endswith(".csv"):
            f = parse_csv
        elif name.endswith(".jsonl"):
            f = parse_jsonl
        else:
            continue
        with open(p, encoding="utf-8", newline="") as fh:
            text = fh.read().replace("\r\n", "\n")
        meta, recs = f(text)
        b = str(meta.get("batch"))
        rev = int(str(meta.get("revision")).strip())
        status = str(meta.get("status", "final")).strip().lower()
        if b not in best or rev > best[b][0]:
            best[b] = (rev, status, recs)
    out = []
    for rev, status, recs in best.values():
        if status != "void":
            out.extend(recs)
    return out


def read_ballot(marks, contest):
    """Returns list of rankings: ('skip',) ('pass',) ('choice', id) ('over',)"""
    cands, wis, maxr = contest["cands"], contest["wi"], contest["max_ranks"]
    seen = set()
    res = []
    for n in range(1, maxr + 1):
        ids = set()
        for kind, v in marks.get(n, []):
            if kind == "wi":
                t = norm_text(v)
                if t in wis:
                    ids.add(wis[t])
            else:
                k = norm_id(v)
                if k in cands:
                    ids.add(k)
        if not ids:
            res.append(("skip",))
            continue
        ids = {i for i in ids if i not in contest["withdrawn"]}
        if not ids:
            res.append(("pass",))
            continue
        new = ids - seen
        seen |= ids
        if not new:
            res.append(("skip",))
        elif len(new) == 1:
            res.append(("choice", next(iter(new))))
        else:
            res.append(("over",))
    return res


def count_for(ranks, continuing):
    n = len(ranks)
    for i, r in enumerate(ranks):
        k = r[0]
        if k == "choice":
            if r[1] in continuing:
                return r[1]
        elif k == "over":
            return None
        elif k == "skip":
            if i + 1 >= n or ranks[i + 1][0] == "skip":
                return None
    return None


def run_contest(c, records):
    maxr = c["max_ranks"]
    cands = {}
    withdrawn = set()
    order = []  # (key, original id)
    for x in c["candidates"]:
        k = norm_id(x["id"])
        cands[k] = x["id"]
        if x.get("status") == "withdrawn":
            withdrawn.add(k)
    wis = {}
    for w in c.get("write_ins", []):
        k = norm_id(w["id"])
        cands[k] = w["id"]
        for t in [w["name"]] + list(w.get("aliases", [])):
            wis.setdefault(norm_text(t), k)
    info = {"cands": cands, "wi": wis, "max_ranks": maxr, "withdrawn": withdrawn}
    ballots = [read_ballot(m, info) for m in records]
    total = len(ballots)
    lot = {norm_id(x): i for i, x in enumerate(c.get("lot_order", []))}
    continuing = [k for k in cands if k not in withdrawn]
    history = []
    rounds = []
    winner = None
    while True:
        cs = set(continuing)
        tal = {k: 0 for k in continuing}
        active = 0
        for b in ballots:
            r = count_for(b, cs)
            if r is not None:
                tal[r] += 1
                active += 1
        history.append(tal)
        rd = {"round": len(rounds) + 1, "tallies": {cands[k]: v for k, v in tal.items()},
              "exhausted": total - active, "eliminated": []}
        rounds.append(rd)
        if active == 0:
            break
        win = [k for k, v in tal.items() if v * 2 > active]
        if win or len(continuing) == 1:
            winner = cands[win[0]] if win else cands[continuing[0]]
            break
        zeros = [k for k in continuing if tal[k] == 0]
        if zeros:
            elim = zeros
        else:
            m = min(tal.values())
            tied = [k for k in continuing if tal[k] == m]
            for h in reversed(history[:-1]):
                if len(tied) == 1:
                    break
                mm = min(h[k] for k in tied)
                tied = [k for k in tied if h[k] == mm]
            if len(tied) > 1:
                tied = [max(tied, key=lambda k: lot.get(k, -1))]
            elim = tied
        rd["eliminated"] = sorted(cands[k] for k in elim)
        continuing = [k for k in continuing if k not in elim]
    return {"contest": c["id"], "ballots": total, "winner": winner, "rounds": rounds}


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, "election.json"), encoding="utf-8") as f:
        el = json.load(f)
    by = {}
    for ballot, contest, marks in load_records(inp):
        by.setdefault(contest, []).append(marks)
    res = {"election": el["election"],
           "contests": [run_contest(c, by.get(c["id"], [])) for c in el["contests"]]}
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


main()
